//! The result document's and the case log entry's types for the TypeScript
//! and Python helpers of `test-support/` that write `journey` documents and
//! case logs (ADRs 0063 and 0069): the bundle's `documents.result_document`
//! and `documents.case_log_entry` and every type they reach, generated by
//! the same outside generators as the SDK layers into each package's
//! `generated/` folder.

use std::collections::BTreeMap;

use anyhow::{Context as _, Result};
use serde_json::{Map, Value};

use super::{External, Generator, projection};

/// `@goodfetch/test-support`'s generated folder.
pub(super) const TYPESCRIPT_FOLDER: &str = "test-support/typescript/src/generated";

/// `goodfetch-test-support`'s generated package.
pub(super) const PYTHON_FOLDER: &str = "test-support/python/src/goodfetch_test_support/generated";

/// The generators' input file name, which `datamodel-code-generator` writes
/// into its header.
const INPUT_NAME: &str = "result-document.json";

/// What every file says first.
const NOTICE: &str = "Generated by `xtask codegen` from the bundle; never edit by hand.";

/// Adds the generated package's `__init__.py` to `files`, and each
/// language's types file to `externals`.
pub(super) fn add(
    bundle: &Value,
    files: &mut BTreeMap<String, Vec<u8>>,
    externals: &mut Vec<External>,
) -> Result<()> {
    files.insert(
        format!("{PYTHON_FOLDER}/__init__.py"),
        format!(
            "\"\"\"The types `xtask codegen` generates for the helpers (ADR 0063).\n\n{NOTICE}\n\"\"\"\n"
        )
        .into_bytes(),
    );
    externals.push(External {
        output: format!("{PYTHON_FOLDER}/result_document.py"),
        generator: Generator::DatamodelCodegen,
        input_name: INPUT_NAME,
        input: Generator::DatamodelCodegen.input_text(input(bundle, true)?)?,
        prefix: String::new(),
        header: format!("\"\"\"The result document's types (ADR 0063).\n\n{NOTICE}\n\"\"\""),
    });
    externals.push(External {
        output: format!("{TYPESCRIPT_FOLDER}/result-document.ts"),
        generator: Generator::Json2ts,
        input_name: INPUT_NAME,
        input: Generator::Json2ts.input_text(input(bundle, false)?)?,
        // The notice comes first, then the generator's output, which has no
        // banner of its own.
        prefix: format!("// {NOTICE}\n\n"),
        header: String::new(),
    });
    Ok(())
}

/// The documents whose types the helpers take: the result document, and the
/// case log entry the case-log writers write (ADR 0069).
const DOCUMENTS: [&str; 2] = ["result_document", "case_log_entry"];

/// The generators' input: a root that holds no value, with every type the
/// documents reach under `$defs`. For Python the root is an empty model,
/// never `RootModel[Any]`.
fn input(bundle: &Value, python: bool) -> Result<Value> {
    let roots = DOCUMENTS
        .iter()
        .map(|name| {
            bundle
                .get("documents")
                .and_then(|documents| documents.get(*name))
                .cloned()
                .with_context(|| format!("the bundle's `documents` maps no `{name}`"))
        })
        .collect::<Result<Vec<Value>>>()?;
    let definitions = bundle
        .get("$defs")
        .and_then(Value::as_object)
        .context("the bundle has no `$defs`")?;
    let reached = projection::reached(&Value::Array(roots), definitions)?;
    let mut input = serde_json::json!({
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "title": "ResultDocumentTypes",
        "description": "The root of the result document's and the case log entry's types, which holds no value of its own.",
        "$defs": definitions
            .iter()
            .filter(|(name, _)| reached.contains(name.as_str()))
            .map(|(name, definition)| (name.clone(), definition.clone()))
            .collect::<Map<String, Value>>(),
    });
    if python {
        input["type"] = Value::from("object");
        input["additionalProperties"] = Value::Bool(false);
        // `datamodel-code-generator` writes an object default as a `dict`
        // literal, which no type checker accepts for a model; without it the
        // field defaults to `None`, and the dump leaves an unset one out.
        if let Some(definitions) = input.get_mut("$defs") {
            drop_object_defaults(definitions);
        }
    }
    Ok(input)
}

/// Removes every `default` whose value is an object.
fn drop_object_defaults(schema: &mut Value) {
    match schema {
        Value::Object(object) => {
            if object.get("default").is_some_and(Value::is_object) {
                object.remove("default");
            }
            object.values_mut().for_each(drop_object_defaults);
        }
        Value::Array(items) => items.iter_mut().for_each(drop_object_defaults),
        _ => {}
    }
}
